package org.ruoyi.service.lawyer;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.ruoyi.common.core.exception.ServiceException;
import org.ruoyi.domain.entity.lawyer.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@Tag("dev") @EnabledIfSystemProperty(named="dossier.mysql",matches="true")
class DossierReviewMysqlTest {
    DossierClaimsMysqlTest flow;DossierReviewService review;BankStatementService bank;
    @BeforeAll static void schema()throws Exception{DossierClaimsMysqlTest.schema();var db=new JdbcTemplate(new DriverManagerDataSource(DossierMaterialsMysqlTest.url,DossierMaterialsMysqlTest.user,DossierMaterialsMysqlTest.password));var sql=Files.readString(DossierMaterialsMysqlTest.workspace.resolve("ruoyi-ai/docs/script/sql/update/2026-10-21-bank-review.sql")).replaceAll("(?m)--.*$","");for(String statement:sql.split(";"))if(!statement.isBlank())db.execute(statement);}
    @BeforeEach void setup()throws Exception{flow=new DossierClaimsMysqlTest();flow.setup();for(String table:List.of("lawyer_case_bank_row","lawyer_case_bank_run","lawyer_case_bank_page","lawyer_case_bank_duplicate","lawyer_case_bank_change","lawyer_case_bank_export"))flow.fixture.jdbc.update("DELETE FROM "+table);bank=new BankStatementService(flow.fixture.jdbc,flow.fixture.tx,flow.fixture.materials,flow.fixture.access);review=new DossierReviewService(flow.anchors,flow.fixture.materials,flow.claims,bank,new DossierReviewAudit(flow.fixture.jdbc),flow.fixture.jdbc,null);flow.fixture.worker.handlers(List.of(flow.extraction,bank));}
    @AfterEach void close(){flow.close();}
    @Test void reviewDeepLinksCheckObjectBindingAndVersionPage()throws Exception{var v=flow.upload("review.pdf","First party statement.","Second page statement.");var a=flow.anchor(v,2,"Second page",0);var c=flow.manual(a);var view=review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),v.getId(),2,a.getId()));assertTrue(view.sources().get(0).verified());assertEquals(a.getId(),view.sources().get(0).anchor().getId());assertThrows(ServiceException.class,()->review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),v.getId(),1,a.getId())));var other=flow.anchor(v,1,"First party",0);assertEquals(404,assertThrows(ServiceException.class,()->review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),v.getId(),1,other.getId()))).getCode());flow.fixture.actor=202;assertThrows(ServiceException.class,()->review.resolve(22L,new DossierReviewService.Pointer("claim",c.getId(),null,null,null)));}
    @Test void fieldCorrectionHasOriginalValueVersionConflictAndMaskedAudit()throws Exception{var a=flow.anchor(flow.upload("fields.pdf","PartyAlpha paid 50000.00."),1,"PartyAlpha paid 50000.00.",0);var c=flow.manual(a);var change=new DossierReviewService.Save(c.getVersion(),"correct",Map.of("text","Human corrected atomic fact","amountRaw","50000.00","name","SyntheticPartyAlpha"),null,"对照原页逐项修改金额和姓名");var saved=review.save(11L,"claim",c.getId(),change);assertEquals("pending_review",saved.reviewStatus());assertTrue(saved.history().stream().flatMap(h->h.fields().stream()).anyMatch(f->f.field().endsWith("amountRaw")&&f.newValue().equals("50000.00")));assertTrue(saved.history().stream().flatMap(h->h.fields().stream()).filter(f->f.field().endsWith("name")).noneMatch(f->f.newValue().contains("SyntheticPartyAlpha")));assertEquals("Synthetic manual claim",saved.fields().stream().filter(f->f.key().equals("text")).findFirst().orElseThrow().original());assertEquals(409,assertThrows(ServiceException.class,()->review.save(11L,"claim",c.getId(),change)).getCode());assertTrue(flow.fixture.jdbc.queryForObject("SELECT after_json FROM lawyer_case_review_change WHERE object_id=? AND action='edit'",String.class,c.getId()).contains("SyntheticPartyAlpha"));}
    @Test void unknownDateCanBeReviewedWithoutInventingAnExactDateAndReplacementExpiresIt()throws Exception{var v=flow.upload("uncertain.pdf","Date of signing is unknown.");var a=flow.anchor(v,1,"Date of signing is unknown.",0);var c=flow.claims.manual(11L,new DossierClaimService.Edit(1,"date","Signing date unknown",new HashMap<>(),List.of(DossierClaimsMysqlTest.supports(a)),"pending_review","原件明确没有可确定日期"));var saved=review.save(11L,"claim",c.getId(),new DossierReviewService.Save(c.getVersion(),"confirm",Map.of("datePrecision","unknown"),null,"人工核对日期无法确定，明确保留未知"));assertEquals("confirmed",saved.reviewStatus());assertEquals("unknown",saved.fields().stream().filter(f->f.key().equals("datePrecision")).findFirst().orElseThrow().value());flow.fixture.upload("changed.pdf",DossierClaimsMysqlTest.pdf("Changed original."),v.getMaterialId(),false);var stale=review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),null,null,null));assertEquals("stale",stale.reviewStatus());assertFalse(stale.sources().get(0).verified());assertThrows(ServiceException.class,()->review.save(11L,"claim",c.getId(),new DossierReviewService.Save(stale.version(),"confirm",Map.of("datePrecision","unknown"),null,"旧来源已失效不能维持确认")));}
    @Test void bankUsesSameRealAnchorAndUnderlyingMoneyGate()throws Exception{String csv="Date,Direction,Amount,Balance,Currency,Ref,Account,Counterparty\n2025-03-01,expense,50000.00,100.00,CNY,SYN-R01,A001,PartyB\n";var v=flow.fixture.upload("review-bank.csv",csv.getBytes(java.nio.charset.StandardCharsets.UTF_8),null,false);flow.fixture.execute(v);bank.classify(11L,v.getMaterialId(),"bank");var job=bank.extract(11L,v.getId(),UUID.randomUUID().toString());String lease=UUID.randomUUID().toString();assertTrue(flow.fixture.worker.claim(job.getId(),lease));flow.fixture.worker.run(job.getId(),lease);var row=bank.list(11L,BankStatementMysqlTest.filter()).rows().get(0);var view=review.resolve(11L,new DossierReviewService.Pointer("bank",row.getId(),v.getId(),1,null));assertTrue(view.sources().get(0).verified());assertEquals(row.getFragmentText(),view.sources().get(0).anchor().getFragmentText());var confirmed=review.save(11L,"bank",row.getId(),new DossierReviewService.Save(view.version(),"confirm",Map.of("amountRaw","50000.10"),null,"逐字段核对原件后人工纠正确认"));assertEquals("confirmed",confirmed.reviewStatus());assertEquals("50000.10",bank.list(11L,BankStatementMysqlTest.filter()).totals().expense());assertTrue(confirmed.history().stream().flatMap(h->h.fields().stream()).anyMatch(f->f.field().equals("amountRaw")&&f.oldValue().equals("50000.00")&&f.newValue().equals("50000.10")));}
    @Test void noSourceCannotConfirmFromUnifiedEntryAndTenReviewsPersistWithoutRecreatingObjects()throws Exception{var no=flow.claims.manual(11L,flow.edit(1,"Unlocated",List.of(),"pending_review"));assertThrows(ServiceException.class,()->review.save(11L,"claim",no.getId(),new DossierReviewService.Save(no.getVersion(),"confirm",Map.of(),null,"缺出处不得从统一入口确认")));var a=flow.anchor(flow.upload("ten.pdf","Ten independent synthetic reviews."),1,"Ten independent",0);var ids=new ArrayList<Long>();for(int i=0;i<10;i++){var c=flow.manual(a);ids.add(c.getId());var view=review.save(11L,"claim",c.getId(),new DossierReviewService.Save(c.getVersion(),"confirm",Map.of("text","Reviewed item "+i),null,"逐条原页核对确认合成条目"));assertEquals("confirmed",view.reviewStatus());}assertEquals(10,flow.fixture.jdbc.queryForObject("SELECT COUNT(*) FROM lawyer_case_claim WHERE review_status='confirmed'",Integer.class));assertEquals(10,new HashSet<>(ids).size());}
    @Test void queueExcludesConfirmedAndForeignObjectsAndSourceExpiryAuditIsAppendOnly()throws Exception{var v=flow.upload("queue.pdf","Source for queue and dependency.");var a=flow.anchor(v,1,"Source for queue",0);var c=flow.manual(a);assertEquals(List.of(c.getId().toString()),review.queue(11L,"claim",List.of(c.getId(),999999L)));var done=review.save(11L,"claim",c.getId(),new DossierReviewService.Save(c.getVersion(),"confirm",Map.of(),null,"队列中逐项核对后确认此条"));assertTrue(review.queue(11L,"claim",List.of(c.getId())).isEmpty());flow.fixture.upload("new-queue.pdf",DossierClaimsMysqlTest.pdf("Replacement source."),v.getMaterialId(),false);var stale=review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),null,null,null));assertEquals("stale",stale.reviewStatus());long auditCount=stale.history().stream().filter(e->e.action().equals("source_dependency")).count();assertEquals(1,auditCount);var again=review.resolve(11L,new DossierReviewService.Pointer("claim",c.getId(),null,null,null));assertEquals(stale.version(),again.version());assertEquals(auditCount,again.history().stream().filter(e->e.action().equals("source_dependency")).count());assertEquals(List.of(c.getId().toString()),review.queue(11L,"claim",List.of(c.getId())));}
}
